import{_ as t,H as a,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"再次起航｜从“旁观者”视角再看消息队列","description":"","frontmatter":{},"headers":[],"relativePath":"消息队列高手课/再次起航｜从“旁观者”视角再看消息队列.md","filePath":"消息队列高手课/再次起航｜从“旁观者”视角再看消息队列.md","lastUpdated":1779821001000}'),r={name:"消息队列高手课/再次起航｜从“旁观者”视角再看消息队列.md"};function i(l,_,o,s,n,d){return a(),e("div",null,[..._[0]||(_[0]=[p('<h1 id="再次起航-从-旁观者-视角再看消息队列" tabindex="-1">再次起航｜从“旁观者”视角再看消息队列 <a class="header-anchor" href="#再次起航-从-旁观者-视角再看消息队列" aria-label="Permalink to &quot;再次起航｜从“旁观者”视角再看消息队列&quot;">​</a></h1><p>你好，我是李玥。</p><p>时光荏苒，从咱们这个专栏发布，距今已经有近 5 年时间了。近几年我工作的技术方向也有一些变化，不再从事消息队列的开发工作，我看消息队列的视角也从“当局者”转换为一个“旁观者”。</p><p>如今再回看这个专栏的内容，结合同学们的留言，我也对这个专栏有了一些新的认知。我发现有些大家很关心的内容，比如消息保序的问题，在专栏中并没有没有讲得很深入。专栏中大部分篇幅在消息队列的原理和相关技术方面，对于工程实践中的一些实际问题涉及不是很全面。我希望把这些内容做一下补充，让这个专栏更加完整。</p><p>这些年在设计和开发其他项目中，我发现有些开发消息队列中使用的经典设计、技术和经验，可以被复用来解决一些通用场景下的特定问题，这些能复用的技术经验类似于我们学习的设计模式，我也希望能把这些“消息队列设计模式”总结出来，在这个专栏中分享给你。</p><p>所以，在接下来的一段时间内，我会开启这个专栏的续写，希望这些内容能对各位同学有所帮助。</p><p><strong>目前拟定增加的话题如下：</strong></p><ul><li>如何实现消息保序？</li><li>如何使用Actor模型解决并发问题？</li><li>Kafka如何保证配置下发的一致性？</li><li>消息队列的高可用与容灾设计</li><li>消息存储读写性能的优化方法</li></ul><p>如果你有更多想要了解的内容，也欢迎在留言区写下你的问题，我们共同探讨！</p><p>另外，由于年底我的工作较为繁忙，也为了内容能够精益求精，加更的部分，频率我会放缓一些，每节课的间隔大致会在一到两周。还请各位同学多多理解！</p><p>好，闲话就到这里。我们课程里见！</p>',11)])])}const m=t(r,[["render",i]]);export{f as __pageData,m as default};
